parameters.jsCode:
const salida = [];
for (const item of $input.all()) {
  const evento = item.json || {};
  const objeto = (evento.data && evento.data.object) || evento.object || {};
  const metadata = objeto.metadata || {};
  const idSesion = String(objeto.id || evento.id || '');
  const referencia = idSesion.slice(-8).toUpperCase();
  const codigoPedido = metadata.codigo || metadata.order_code || metadata.codigo_pedido || ('PED-' + idSesion.slice(-4).toUpperCase());
  const nombre = metadata.cliente_nombre || metadata.nombre || 'Cliente';
  const telefono = metadata.telefono || metadata.cliente_telefono || 'Sin teléfono';
  const correo = metadata.correo || metadata.cliente_correo || metadata.email || '';
  const direccion = metadata.direccion || metadata.cliente_direccion || 'Sin dirección';
  const mesa = metadata.mesa || '';
  const tipo_entrega = metadata.tipo_entrega || metadata.tipo || 'domicilio';
  const total = metadata.total_centimos ? Number(metadata.total_centimos) / 100 : (Number(objeto.amount_total) || 0) / 100;
  const total_texto = metadata.total_texto || total.toFixed(2);
  let items = [];
  try {
    const parseado = JSON.parse(metadata.detalle || metadata.items || '[]');
    if (Array.isArray(parseado)) items = parseado;
  } catch (e) { items = []; }
  const detalle_texto = metadata.detalle_texto || items.map(it => {
    const precio = typeof it.precio === 'number' ? it.precio.toFixed(2).replace('.', ',') + ' €' : it.precio || '';
    const unidades = (it.cantidad || it.qty || 1) > 1 ? (it.cantidad || it.qty) + ' x ' : '';
    return unidades + (it.nombre || it.name || '') + ' - ' + precio;
  }).join('\n');
  salida.push({
    json: {
      ...evento,
      order_code: codigoPedido,
      codigo_pedido: codigoPedido,
      cliente_nombre: nombre,
      cliente_telefono: telefono,
      cliente_correo: correo,
      direccion: direccion,
      mesa: mesa,
      tipo_entrega: tipo_entrega,
      total: total,
      total_centimos: Math.round(total * 100),
      total_texto: total_texto,
      detalle_texto: detalle_texto,
      pedido_id: metadata.pedido_id || codigoPedido,
      referencia: referencia,
      pagado: true
    },
  });
}
return salida;

